import React from 'react';
import { useClassElement } from '../hooks/useClassElement';

export function ClassTest() {
  const testElement = useClassElement({
    elementId: 'test-element',
    classId: 'fake-branding',
    trigger: 'hover',
    position: 'top'
  });

  return (
    <div style={{ 
      position: 'fixed', 
      top: '50px', 
      left: '10px', 
      zIndex: 9999,
      background: 'red',
      color: 'white',
      padding: '10px',
      cursor: 'help'
    }}
    ref={testElement.ref}
    {...testElement.eventHandlers}
    onMouseEnter={() => console.log('Test element mouse enter')}
    onMouseLeave={() => console.log('Test element mouse leave')}
    >
      🧪 TEST - Hover over me!
    </div>
  );
}
